-- Flowwithlit core platform baseline. Safe to run repeatedly; it never drops data.
CREATE DATABASE IF NOT EXISTS flowwithlit_db CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE flowwithlit_db;

CREATE TABLE IF NOT EXISTS schema_migrations (version VARCHAR(100) PRIMARY KEY, applied_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS users (
 id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, uuid CHAR(36) NOT NULL UNIQUE, account_type ENUM('individual','business') NOT NULL DEFAULT 'individual', full_name VARCHAR(150) NOT NULL, email VARCHAR(191) NOT NULL UNIQUE, phone VARCHAR(30) NULL UNIQUE, password_hash VARCHAR(255) NULL, flow_tag VARCHAR(50) NOT NULL UNIQUE, auth_provider ENUM('email','google') NOT NULL DEFAULT 'email', google_id VARCHAR(255) NULL UNIQUE, avatar_url VARCHAR(500) NULL, email_verified TINYINT(1) NOT NULL DEFAULT 0, two_factor_enabled TINYINT(1) NOT NULL DEFAULT 0, two_factor_secret VARCHAR(255) NULL, kyc_tier TINYINT UNSIGNED NOT NULL DEFAULT 1, status ENUM('active','pending_verification','suspended','closed') NOT NULL DEFAULT 'pending_verification', created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, INDEX idx_users_status(status)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
ALTER TABLE users ADD COLUMN IF NOT EXISTS withdrawal_pin_hash VARCHAR(255) NULL AFTER password_hash;
ALTER TABLE users ADD COLUMN IF NOT EXISTS last_login_at DATETIME NULL AFTER updated_at;

CREATE TABLE IF NOT EXISTS user_profiles (user_id INT UNSIGNED PRIMARY KEY, date_of_birth DATE NULL, country_code CHAR(2) NULL, address_line1 VARCHAR(191) NULL, address_line2 VARCHAR(191) NULL, city VARCHAR(100) NULL, state_region VARCHAR(100) NULL, postal_code VARCHAR(30) NULL, preferences JSON NULL, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS devices (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id INT UNSIGNED NOT NULL, device_id VARCHAR(191) NOT NULL, platform ENUM('web','ios','android') NOT NULL, push_token VARCHAR(512) NULL, last_seen_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE KEY uq_device(user_id,device_id), FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS user_sessions (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id INT UNSIGNED NOT NULL, token_hash CHAR(64) NOT NULL UNIQUE, device_info VARCHAR(255) NULL, ip_address VARCHAR(45) NOT NULL, is_2fa_verified TINYINT(1) NOT NULL DEFAULT 1, expires_at DATETIME NOT NULL, last_activity DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, INDEX idx_session_user_expiry(user_id,expires_at), FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS refresh_tokens (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id INT UNSIGNED NOT NULL, token_hash CHAR(64) NOT NULL UNIQUE, device_id VARCHAR(191) NULL, expires_at DATETIME NOT NULL, revoked_at DATETIME NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS verification_codes (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id INT UNSIGNED NULL, email VARCHAR(191) NOT NULL, code VARCHAR(10) NOT NULL, type ENUM('email_verification','password_reset','2fa') NOT NULL, is_used TINYINT(1) NOT NULL DEFAULT 0, expires_at DATETIME NOT NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, INDEX idx_code_lookup(email,code,type,is_used), FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS login_attempts (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, ip_address VARCHAR(45) NOT NULL, email VARCHAR(191) NOT NULL, attempts TINYINT UNSIGNED NOT NULL DEFAULT 1, last_attempt DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE KEY uq_attempt(ip_address,email)) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS businesses (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, uuid CHAR(36) NOT NULL UNIQUE, owner_user_id INT UNSIGNED NOT NULL, legal_name VARCHAR(191) NOT NULL, trading_name VARCHAR(191) NULL, registration_number VARCHAR(100) NULL, business_type ENUM('sole_proprietor','partnership','limited_company','nonprofit','other') NOT NULL, industry VARCHAR(100) NULL, website_url VARCHAR(255) NULL, support_email VARCHAR(191) NULL, support_phone VARCHAR(30) NULL, logo_url VARCHAR(500) NULL, verification_status ENUM('draft','submitted','under_review','approved','rejected') NOT NULL DEFAULT 'draft', created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, INDEX idx_business_owner(owner_user_id), FOREIGN KEY(owner_user_id) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS business_members (business_id INT UNSIGNED NOT NULL, user_id INT UNSIGNED NOT NULL, role ENUM('owner','admin','developer','viewer') NOT NULL DEFAULT 'viewer', created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(business_id,user_id), FOREIGN KEY(business_id) REFERENCES businesses(id) ON DELETE CASCADE, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS business_documents (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, business_id INT UNSIGNED NOT NULL, document_type ENUM('registration','address_proof','bank_statement','identity','other') NOT NULL, file_key VARCHAR(500) NOT NULL, status ENUM('uploaded','accepted','rejected') NOT NULL DEFAULT 'uploaded', reviewed_by INT UNSIGNED NULL, review_note VARCHAR(500) NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(business_id) REFERENCES businesses(id) ON DELETE CASCADE, FOREIGN KEY(reviewed_by) REFERENCES users(id)) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS currencies (code VARCHAR(12) PRIMARY KEY, name VARCHAR(80) NOT NULL, kind ENUM('fiat','crypto') NOT NULL, decimals TINYINT UNSIGNED NOT NULL, network VARCHAR(50) NULL, is_enabled TINYINT(1) NOT NULL DEFAULT 1) ENGINE=InnoDB;
INSERT IGNORE INTO currencies(code,name,kind,decimals) VALUES ('NGN','Nigerian Naira','fiat',2),('USD','US Dollar','fiat',2),('EUR','Euro','fiat',2),('GBP','British Pound','fiat',2),('USDT','Tether','crypto',6),('USDC','USD Coin','crypto',6),('BTC','Bitcoin','crypto',8),('ETH','Ethereum','crypto',18),('SOL','Solana','crypto',9);
CREATE TABLE IF NOT EXISTS wallets (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, uuid CHAR(36) NOT NULL UNIQUE, user_id INT UNSIGNED NOT NULL, business_id INT UNSIGNED NULL, currency_code VARCHAR(12) NOT NULL, wallet_type ENUM('personal','business','reserve') NOT NULL DEFAULT 'personal', available_balance DECIMAL(36,18) NOT NULL DEFAULT 0, pending_balance DECIMAL(36,18) NOT NULL DEFAULT 0, status ENUM('active','frozen','closed') NOT NULL DEFAULT 'active', created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, UNIQUE KEY uq_wallet_owner_currency(user_id,business_id,currency_code,wallet_type), FOREIGN KEY(user_id) REFERENCES users(id), FOREIGN KEY(business_id) REFERENCES businesses(id), FOREIGN KEY(currency_code) REFERENCES currencies(code)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS bank_accounts (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id INT UNSIGNED NOT NULL, business_id INT UNSIGNED NULL, bank_name VARCHAR(120) NOT NULL, account_name VARCHAR(191) NOT NULL, account_number_encrypted TEXT NOT NULL, account_number_last4 CHAR(4) NOT NULL, bank_code VARCHAR(30) NULL, currency_code VARCHAR(12) NOT NULL, status ENUM('pending','verified','disabled') NOT NULL DEFAULT 'pending', created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(id), FOREIGN KEY(business_id) REFERENCES businesses(id), FOREIGN KEY(currency_code) REFERENCES currencies(code)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS beneficiaries (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id INT UNSIGNED NOT NULL, nickname VARCHAR(100) NULL, beneficiary_type ENUM('bank','flowwithlit','crypto') NOT NULL, details_encrypted TEXT NOT NULL, status ENUM('active','disabled') NOT NULL DEFAULT 'active', created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS transactions (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, uuid CHAR(36) NOT NULL UNIQUE, user_id INT UNSIGNED NOT NULL, business_id INT UNSIGNED NULL, type ENUM('deposit','withdrawal','transfer','swap','payment','refund','fee','adjustment') NOT NULL, status ENUM('initiated','pending','processing','completed','failed','reversed','cancelled') NOT NULL DEFAULT 'initiated', source_wallet_id INT UNSIGNED NULL, destination_wallet_id INT UNSIGNED NULL, currency_code VARCHAR(12) NOT NULL, amount DECIMAL(36,18) NOT NULL, fee_amount DECIMAL(36,18) NOT NULL DEFAULT 0, reference VARCHAR(100) NOT NULL UNIQUE, idempotency_key VARCHAR(191) NULL UNIQUE, provider VARCHAR(80) NULL, provider_reference VARCHAR(191) NULL, metadata JSON NULL, completed_at DATETIME NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, INDEX idx_tx_user_created(user_id,created_at), INDEX idx_tx_status(status), FOREIGN KEY(user_id) REFERENCES users(id), FOREIGN KEY(business_id) REFERENCES businesses(id), FOREIGN KEY(source_wallet_id) REFERENCES wallets(id), FOREIGN KEY(destination_wallet_id) REFERENCES wallets(id), FOREIGN KEY(currency_code) REFERENCES currencies(code)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS ledger_accounts (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, wallet_id INT UNSIGNED NULL UNIQUE, account_code VARCHAR(80) NOT NULL UNIQUE, account_type ENUM('asset','liability','revenue','expense','equity') NOT NULL, name VARCHAR(191) NOT NULL, currency_code VARCHAR(12) NOT NULL, FOREIGN KEY(wallet_id) REFERENCES wallets(id), FOREIGN KEY(currency_code) REFERENCES currencies(code)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS ledger_entries (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, uuid CHAR(36) NOT NULL UNIQUE, transaction_id INT UNSIGNED NULL, description VARCHAR(255) NOT NULL, posted_at DATETIME NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(transaction_id) REFERENCES transactions(id), INDEX idx_ledger_tx(transaction_id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS ledger_lines (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, ledger_entry_id INT UNSIGNED NOT NULL, ledger_account_id INT UNSIGNED NOT NULL, direction ENUM('debit','credit') NOT NULL, amount DECIMAL(36,18) NOT NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(ledger_entry_id) REFERENCES ledger_entries(id) ON DELETE CASCADE, FOREIGN KEY(ledger_account_id) REFERENCES ledger_accounts(id), INDEX idx_line_account(ledger_account_id)) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS payment_links (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, uuid CHAR(36) NOT NULL UNIQUE, user_id INT UNSIGNED NOT NULL, business_id INT UNSIGNED NULL, public_token VARCHAR(80) NOT NULL UNIQUE, title VARCHAR(191) NOT NULL, description TEXT NULL, amount DECIMAL(36,18) NULL, currency_code VARCHAR(12) NOT NULL, status ENUM('active','expired','disabled') NOT NULL DEFAULT 'active', expires_at DATETIME NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(id), FOREIGN KEY(business_id) REFERENCES businesses(id), FOREIGN KEY(currency_code) REFERENCES currencies(code)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS payments (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, payment_link_id INT UNSIGNED NULL, transaction_id INT UNSIGNED NOT NULL UNIQUE, customer_email VARCHAR(191) NULL, customer_name VARCHAR(191) NULL, status ENUM('pending','succeeded','failed','refunded') NOT NULL DEFAULT 'pending', created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(payment_link_id) REFERENCES payment_links(id), FOREIGN KEY(transaction_id) REFERENCES transactions(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS swaps (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, transaction_id INT UNSIGNED NOT NULL UNIQUE, from_currency_code VARCHAR(12) NOT NULL, to_currency_code VARCHAR(12) NOT NULL, from_amount DECIMAL(36,18) NOT NULL, to_amount DECIMAL(36,18) NOT NULL, exchange_rate DECIMAL(36,18) NOT NULL, quoted_at DATETIME NOT NULL, FOREIGN KEY(transaction_id) REFERENCES transactions(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS cards (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, uuid CHAR(36) NOT NULL UNIQUE, user_id INT UNSIGNED NOT NULL, wallet_id INT UNSIGNED NOT NULL, provider VARCHAR(80) NOT NULL, provider_card_id VARCHAR(191) NOT NULL UNIQUE, card_type ENUM('virtual','physical') NOT NULL, last4 CHAR(4) NOT NULL, status ENUM('active','frozen','terminated') NOT NULL DEFAULT 'active', spending_limit DECIMAL(36,18) NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(id), FOREIGN KEY(wallet_id) REFERENCES wallets(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS api_keys (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, business_id INT UNSIGNED NOT NULL, name VARCHAR(100) NOT NULL, key_prefix VARCHAR(20) NOT NULL, secret_hash CHAR(64) NOT NULL UNIQUE, environment ENUM('test','live') NOT NULL DEFAULT 'test', last_used_at DATETIME NULL, revoked_at DATETIME NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(business_id) REFERENCES businesses(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS webhook_endpoints (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, business_id INT UNSIGNED NOT NULL, url VARCHAR(500) NOT NULL, secret_hash CHAR(64) NOT NULL, events JSON NOT NULL, status ENUM('active','disabled') NOT NULL DEFAULT 'active', created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(business_id) REFERENCES businesses(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS webhook_deliveries (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, webhook_endpoint_id INT UNSIGNED NOT NULL, event_type VARCHAR(100) NOT NULL, payload JSON NOT NULL, response_status SMALLINT NULL, attempts TINYINT UNSIGNED NOT NULL DEFAULT 0, delivered_at DATETIME NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(webhook_endpoint_id) REFERENCES webhook_endpoints(id) ON DELETE CASCADE, INDEX idx_delivery_status(webhook_endpoint_id,delivered_at)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS notifications (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id INT UNSIGNED NOT NULL, type VARCHAR(80) NOT NULL, title VARCHAR(191) NOT NULL, body TEXT NOT NULL, action_url VARCHAR(500) NULL, data JSON NULL, read_at DATETIME NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, INDEX idx_notification_user_read(user_id,read_at,created_at), FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS audit_logs (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id INT UNSIGNED NULL, business_id INT UNSIGNED NULL, action VARCHAR(120) NOT NULL, entity_type VARCHAR(80) NOT NULL, entity_id VARCHAR(100) NULL, ip_address VARCHAR(45) NULL, user_agent VARCHAR(255) NULL, context JSON NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, INDEX idx_audit_entity(entity_type,entity_id), INDEX idx_audit_user(user_id,created_at), FOREIGN KEY(user_id) REFERENCES users(id), FOREIGN KEY(business_id) REFERENCES businesses(id)) ENGINE=InnoDB;

INSERT IGNORE INTO schema_migrations(version) VALUES ('001_core_platform');
